import { isParseConfigured, parseQuery } from './parse-server';

/** Study notes a learner keeps for a module: written by hand or generated by the AI from their own mistakes. */
export const NOTE_CLASS = 'StudyNote';
export const NOTE_FIELDS = {
  studentEmail: { type: 'String' },
  courseSlug: { type: 'String' },
  courseTitle: { type: 'String' },
  lessonIndex: { type: 'Number' },
  title: { type: 'String' },
  content: { type: 'String' },
  source: { type: 'String' },
  createdAtIso: { type: 'String' },
} as const;

export type NoteRow = {
  objectId: string; studentEmail: string; courseSlug: string; courseTitle?: string; lessonIndex: number;
  title: string; content: string; source: 'ai' | 'manual'; createdAtIso?: string;
};

/** AI notes are stored as JSON; hand-written notes as plain text. */
export type AiNoteContent = {
  mistakes: { question: string; whyWrong: string; tip: string }[];
  notes: string[];
  guidelines: string[];
};

export function mapNote(row: NoteRow) {
  let ai: AiNoteContent | null = null;
  if (row.source === 'ai') {
    try { ai = JSON.parse(row.content) as AiNoteContent; } catch { ai = null; }
  }
  return {
    id: row.objectId,
    courseSlug: row.courseSlug,
    courseTitle: row.courseTitle || '',
    lessonIndex: row.lessonIndex,
    title: row.title,
    source: row.source,
    text: row.source === 'manual' ? row.content : '',
    ai,
    createdAt: row.createdAtIso || '',
  };
}

export async function findNotes(where: Record<string, unknown>, limit = 100) {
  if (!isParseConfigured()) return [] as NoteRow[];
  try {
    return (await parseQuery<NoteRow>(NOTE_CLASS, { where: JSON.stringify(where), limit, order: '-createdAt' })).results || [];
  } catch { return []; }
}
